import { buttonMessages } from "@dashboard/intl";
import { Box, Button, type ButtonProps, Tooltip } from "@saleor/macaw-ui-next";
import type * as React from "react";
import { FormattedMessage } from "react-intl";

import {
  ConfirmButton as ConfirmButtonComponent,
  type ConfirmButtonProps,
} from "../ConfirmButton/ConfirmButton";

export const DeleteButton = ({
  children,
  ...props
}: { children?: React.ReactNode } & ButtonProps) => (
  <Button variant="error" size="large" data-test-id="button-bar-delete" {...props} type="button">
    {children || <FormattedMessage {...buttonMessages.delete} />}
  </Button>
);

export const ConfirmButton = ({
  children,
  transitionState,
  tooltip,
  disabled,
  ...props
}: {
  children?: React.ReactNode;
  transitionState: ConfirmButtonProps["transitionState"];
  tooltip?: React.ReactNode;
} & ButtonProps) => {
  const button = (
    <ConfirmButtonComponent
      size="large"
      transitionState={transitionState}
      data-test-id="button-bar-confirm"
      disabled={disabled}
      {...props}
    >
      {children || <FormattedMessage {...buttonMessages.save} />}
    </ConfirmButtonComponent>
  );

  if (tooltip && disabled) {
    return (
      <Tooltip>
        <Tooltip.Trigger>
          {/* Box wrapper needed to capture hover events on disabled button */}
          <Box display="inline-block">{button}</Box>
        </Tooltip.Trigger>
        <Tooltip.Content side="top">
          <Tooltip.Arrow />
          {tooltip}
        </Tooltip.Content>
      </Tooltip>
    );
  }

  return button;
};

